//! Zero-touch feature discovery.
//!
//! Every feature self-registers here via [`inventory::submit!`]: the DI part
//! through a [`Feature`] (repository + service) and the HTTP part through the
//! [`Route`]s generated by the [`framework_macros::route`] attribute on each
//! handler. `features.rs`, `router.rs` and `docs.rs` know nothing about
//! individual features: they only iterate these registries, so adding a new
//! feature no longer requires any line in the wiring files.

use std::sync::Arc;

use axum::Router;
use di::singleton_factory;
use di::{ServiceCollection, ServiceProvider};
use utoipa::openapi::OpenApi;

use crate::db;

/// Feature self-registered in the registry.
///
/// It is not a runtime object: it is a static value describing which
/// dependencies the feature requires in the DI container.
pub struct Feature {
    /// Registration order in the container: a feature's dependencies must be
    /// registered before the code that uses them (lazy injection in `more-di`
    /// makes the order tolerant, but keeping it explicit is safer).
    pub order: u8,
    /// Registers the feature's repository and service in the DI container.
    pub register: fn(repositories: &db::Repositories, services: &mut ServiceCollection),
}

impl Feature {
    pub const fn new(
        order: u8,
        register: fn(repositories: &db::Repositories, services: &mut ServiceCollection),
    ) -> Self {
        Self { order, register }
    }
}

// Collects all occurrences of [`Feature`] in the static registry.
// `collect!` must live in the crate that defines the type: it is here, and all
// features can then register themselves with `inventory::submit!`.
inventory::collect!(Feature);

/// A single route, registered by the [`framework_macros::route`] attribute on
/// its handler.
///
/// The builder resolves the handler's service from the DI provider and mounts
/// the axum router + OpenAPI fragment for that handler.
pub struct Route {
    pub build: fn(provider: &ServiceProvider) -> (Router, OpenApi),
}

impl Route {
    pub const fn new(build: fn(provider: &ServiceProvider) -> (Router, OpenApi)) -> Self {
        Self { build }
    }
}

// Collects every route generated by `#[route]`.
inventory::collect!(Route);

/// Registers an already-built dependency (a repository) in the DI under its
/// trait, simplifying the registration line of every feature.
pub fn register_repository<S: ?Sized + Send + Sync + 'static>(
    services: &mut ServiceCollection,
    repository: Arc<S>,
) {
    services.add(singleton_factory::<S, _>(move |_| -> di::Ref<S> {
        repository.clone()
    }));
}
